const items = $input.all();

if (items.length !== 1) {
  throw new Error(
    `Lifecycle request must contain exactly 1 item; received ${items.length}.`
  );
}

const input = items[0].json ?? {};

// Validate anomaly_id.
// Accept a positive integer or a decimal string such as "123".
const rawId = input.anomaly_id;

let anomalyId;

if (typeof rawId === 'number') {
  anomalyId = rawId;
} else if (
  typeof rawId === 'string' &&
  /^\d+$/.test(rawId.trim())
) {
  anomalyId = Number(rawId.trim());
} else {
  throw new Error('anomaly_id must be a positive integer.');
}

if (!Number.isSafeInteger(anomalyId) || anomalyId <= 0) {
  throw new Error('anomaly_id must be a positive integer.');
}

// Validate action.
if (typeof input.action !== 'string') {
  throw new Error(
    'action is required and must be either "acknowledge" or "resolve".'
  );
}

const action = input.action.trim();

if (!['acknowledge', 'resolve'].includes(action)) {
  throw new Error(
    'action must be either "acknowledge" or "resolve".'
  );
}

// Validate resolution_reason according to action.
let resolutionReason = input.resolution_reason ?? null;

if (action === 'resolve') {
  if (
    typeof resolutionReason !== 'string' ||
    resolutionReason.trim().length === 0
  ) {
    throw new Error(
      'resolution_reason is required when action is "resolve".'
    );
  }

  resolutionReason = resolutionReason.trim();
} else {
  if (
    resolutionReason !== null &&
    resolutionReason !== undefined &&
    String(resolutionReason).trim().length > 0
  ) {
    throw new Error(
      'resolution_reason is only allowed when action is "resolve".'
    );
  }

  resolutionReason = null;
}

return [
  {
    json: {
      anomaly_id: anomalyId,
      action,
      resolution_reason: resolutionReason
    }
  }
];

const items = $input.all();

if (items.length !== 1) {
  throw new Error(
    `Expected exactly 1 database result; received ${items.length}.`
  );
}

const current = items[0].json ?? {};

// Recover the already validated request.
// We deliberately use the validated node rather than the original test input.
const request = $('Validate Lifecycle Request').first().json;

const requestedId = request.anomaly_id;
const action = request.action;
const resolutionReason = request.resolution_reason ?? null;

// The LEFT JOIN in Read Current Anomaly guarantees one row.
// A null anomaly_id therefore means the requested anomaly does not exist.
if (current.anomaly_id === null || current.anomaly_id === undefined) {
  throw new Error(`Anomaly ${requestedId} was not found.`);
}

const currentStatus = current.current_status;

if (!['open', 'acknowledged', 'resolved'].includes(currentStatus)) {
  throw new Error(
    `Anomaly ${requestedId} has unsupported lifecycle status "${currentStatus}".`
  );
}

let targetStatus;

if (action === 'acknowledge') {
  if (currentStatus !== 'open') {
    throw new Error(
      `Illegal lifecycle transition: "${currentStatus}" cannot be acknowledged.`
    );
  }

  targetStatus = 'acknowledged';
}

if (action === 'resolve') {
  if (currentStatus !== 'acknowledged') {
    throw new Error(
      `Illegal lifecycle transition: "${currentStatus}" cannot be resolved.`
    );
  }

  targetStatus = 'resolved';
}

if (!targetStatus) {
  throw new Error(`Unsupported lifecycle action "${action}".`);
}

return [
  {
    json: {
      anomaly_id: Number(requestedId),
      action,
      expected_status: currentStatus,
      target_status: targetStatus,
      resolution_reason: resolutionReason,
      symbol: current.symbol,
      anomaly_type: current.anomaly_type,
      severity: current.severity
    }
  }
];

const items = $input.all();

if (items.length !== 1) {
  throw new Error(
    `Expected exactly 1 transition result; received ${items.length}.`
  );
}

const result = items[0].json ?? {};

if (result.transition_applied !== true) {
  throw new Error(
    `Lifecycle transition was not applied for anomaly ${result.requested_anomaly_id}; ` +
    `expected current status "${result.expected_status}". ` +
    'The anomaly may have changed concurrently.'
  );
}

if (
  result.anomaly_id === null ||
  result.anomaly_id === undefined
) {
  throw new Error(
    `Lifecycle transition reported success without an anomaly row.`
  );
}

if (result.status !== result.target_status) {
  throw new Error(
    `Lifecycle transition verification failed: expected target status ` +
    `"${result.target_status}" but received "${result.status}".`
  );
}

return items;

const items = $input.all();

if (items.length !== 1) {
  throw new Error(
    `Webhook request must contain exactly 1 item; received ${items.length}.`
  );
}

const input = items[0].json ?? {};
const body = input.body;

if (
  body === null ||
  typeof body !== 'object' ||
  Array.isArray(body)
) {
  throw new Error('Webhook request body must be a JSON object.');
}

return [
  {
    json: {
      anomaly_id: body.anomaly_id,
      action: body.action,
      resolution_reason: body.resolution_reason ?? null
    }
  }
];

const items = $input.all();

if (items.length !== 1) {
  throw new Error(
    `Expected exactly 1 error item; received ${items.length}.`
  );
}

const input = items[0].json ?? {};

const rawError =
  typeof input.error === 'string'
    ? input.error
    : 'Unexpected lifecycle error.';

// Remove n8n implementation detail such as "[line 22]"
// from the API-visible error message.
const message = rawError
  .replace(/\s*\[line \d+\]\s*$/i, '')
  .trim();

let httpStatus = 500;
let errorCode = 'internal_error';

if (/^Anomaly \d+ was not found\.$/.test(message)) {
  httpStatus = 404;
  errorCode = 'anomaly_not_found';
} else if (
  message.startsWith('Illegal lifecycle transition:') ||
  /^"(open|acknowledged|resolved)" cannot be (acknowledged|resolved)\.$/.test(message)
) {
  httpStatus = 409;
  errorCode = 'illegal_transition';
} else if (
  message.includes('The anomaly may have changed concurrently.')
) {
  httpStatus = 409;
  errorCode = 'concurrent_state_change';
} else if (
  message.startsWith('anomaly_id must') ||
  message.startsWith('action is required') ||
  message.startsWith('action must') ||
  message.startsWith('resolution_reason is required') ||
  message.startsWith('resolution_reason is only allowed') ||
  message.startsWith('Lifecycle request must') ||
  message.startsWith('Webhook request body must')
) {
  httpStatus = 400;
  errorCode = 'invalid_request';
}

return [
  {
    json: {
      success: false,
      http_status: httpStatus,
      error_code: errorCode,
      error_message: message
    }
  }
];
